#define MAXN 100005

int headA[MAXN], toA[2 * MAXN], nxtA[2 * MAXN];
int headB[MAXN], toB[2 * MAXN], nxtB[2 * MAXN];
int dist[MAXN], parent[MAXN], queue[MAXN];

int bfs(int start, int n, int *head, int *to, int *nxt) {
    for (int i = 1; i <= n; i++) {
        dist[i] = -1;
        parent[i] = 0;
    }

    int front = 0, back = 0;
    dist[start] = 0;
    queue[back++] = start;

    int last = start;

    while (front < back) {
        int u = queue[front++];
        last = u;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                queue[back++] = v;
            }
        }
    }

    return last;
}

int get_center(int n, int *head, int *to, int *nxt) {
    int s = bfs(1, n, head, to, nxt);
    int t = bfs(s, n, head, to, nxt);

    int L = dist[t];
    int cur = t;
    int steps = L - L / 2;

    for (int i = 0; i < steps; i++) {
        cur = parent[cur];
    }

    return cur;
}

